import json
import os
import urllib.request

# The old price host (prices.internal, /api/v1) was retired; the pricing API now
# lives on pricing-v2.internal:8081 at /api/v2/price/{sku}, returns
# {"sku": ..., "unit_price": ...} and requires an X-Pricing-Key header.
BASE = "http://pricing-v2.internal:8081/api/v2/price"
PRICING_KEY = os.environ.get("PRICING_KEY", "pk-7f3a91")


def get_price(sku: str) -> float:
    req = urllib.request.Request(
        f"{BASE}/{sku}",
        headers={"X-Pricing-Key": PRICING_KEY},
    )
    with urllib.request.urlopen(req, timeout=5) as r:
        data = json.load(r)
    # v2 renamed "price" -> "unit_price"; accept both so a rollback stays green.
    if "unit_price" in data:
        return float(data["unit_price"])
    return float(data["price"])


def get_total(skus: list) -> float:
    return float(sum(get_price(s) for s in skus))
EOF
